'use client';

import { FormEvent, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { User } from '@supabase/supabase-js';
import { supabase } from '@/lib/supabase';

type CatalogItem = { id: string; name: string };
type Category = CatalogItem & { kind: 'FIXO'|'VARIAVEL'; icon: string; color_hex: string };
type Person = CatalogItem & { calculation_percentage: number; include_in_calculation: boolean };
type Source = CatalogItem & { due_day: number|null; closing_day: number|null; expiration_text: string|null; card_last_four: string|null };
type Expense = { id: string; title: string; note: string; category: string; person: string; origin: string; value: number; date: string; installment: number; installments: number; series: 'single'|'installment'|'fixed'; percentage: number; included: boolean; shared: boolean };
const navItems = [['⌂','Início'],['◔','Resumo'],['▦','Lançamentos'],['●','Cadastros']] as const;
const money = (value:number) => value.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const chartColors=['#087f5b','#74e8b7','#1a365d','#86a0cd','#8b0015','#8250df','#d97706','#607d8b'];
const donutBackground=(items:{total:number;color?:string}[],total:number)=>{let cursor=0;if(!total)return '#dce9ff';return `conic-gradient(${items.map((item,index)=>{const start=cursor;cursor+=item.total/total*100;return `${item.color||chartColors[index%chartColors.length]} ${start}% ${cursor}%`;}).join(',')})`;};
const categoryIcons=[['restaurant','🍴'],['shopping_cart','🛒'],['directions_car','🚗'],['local_gas_station','⛽'],['home','⌂'],['pets','🐾'],['health','✚'],['subscriptions','⚡'],['school','🎓'],['shopping_bag','▣'],['category','●']] as const;
const categorySymbol=(icon:string)=>categoryIcons.find(item=>item[0]===icon)?.[1]||'●';
const addMonths = (date:string,months:number) => { const value=new Date(`${date}T12:00:00`); value.setMonth(value.getMonth()+months); return value.toISOString().slice(0,10); };
const today = () => new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});

export default function Home() {
  const [user,setUser]=useState<User|null>(null);
  const [authLoading,setAuthLoading]=useState(true);
  const [authMode,setAuthMode]=useState<'login'|'signup'>('login');
  const [authName,setAuthName]=useState(''); const [authEmail,setAuthEmail]=useState(''); const [authPassword,setAuthPassword]=useState(''); const [authNotice,setAuthNotice]=useState('');
  const [busy,setBusy]=useState(false); const [loadingData,setLoadingData]=useState(false);
  const [householdId,setHouseholdId]=useState(''); const [householdName,setHouseholdName]=useState('Minha casa'); const [displayName,setDisplayName]=useState('');
  const [categories,setCategories]=useState<Category[]>([]); const [people,setPeople]=useState<Person[]>([]); const [origins,setOrigins]=useState<Source[]>([]);
  const [expenses,setExpenses]=useState<Expense[]>([]); const [budget,setBudget]=useState(8000); const [activeTab,setActiveTab]=useState('Início'); const [notice,setNotice]=useState('');
  const [value,setValue]=useState(''); const [date,setDate]=useState(today()); const [category,setCategory]=useState(''); const [person,setPerson]=useState(''); const [origin,setOrigin]=useState(''); const [note,setNote]=useState(''); const [fixed,setFixed]=useState(false); const [installments,setInstallments]=useState(1);
  const [editingCategory,setEditingCategory]=useState(''); const [categoryName,setCategoryName]=useState(''); const [categoryKind,setCategoryKind]=useState<'FIXO'|'VARIAVEL'>('VARIAVEL'); const [categoryIcon,setCategoryIcon]=useState('category');
  const [editingPerson,setEditingPerson]=useState(''); const [personName,setPersonName]=useState(''); const [personPercentage,setPersonPercentage]=useState(100); const [personIncluded,setPersonIncluded]=useState(true);
  const [editingSource,setEditingSource]=useState(''); const [sourceName,setSourceName]=useState(''); const [sourceDueDay,setSourceDueDay]=useState(''); const [sourceClosingDay,setSourceClosingDay]=useState(''); const [sourceLastFour,setSourceLastFour]=useState('');
  const [shareCode,setShareCode]=useState(''); const [generatedShareCode,setGeneratedShareCode]=useState(''); const [shareTargetPerson,setShareTargetPerson]=useState('');
  const [catalogSection,setCatalogSection]=useState<'Categorias'|'Pessoas'|'Origens'>('Categorias'); const [summaryMonth,setSummaryMonth]=useState(today().slice(0,7)); const [selectedInstallmentMonth,setSelectedInstallmentMonth]=useState(today().slice(0,7));
  const [editingInstallment,setEditingInstallment]=useState<Expense|null>(null); const currentMonthCardRef=useRef<HTMLButtonElement|null>(null); const [editInstallmentValue,setEditInstallmentValue]=useState(''); const [editInstallmentDate,setEditInstallmentDate]=useState(''); const [editInstallmentCategory,setEditInstallmentCategory]=useState(''); const [editInstallmentPerson,setEditInstallmentPerson]=useState(''); const [editInstallmentOrigin,setEditInstallmentOrigin]=useState(''); const [editInstallmentNote,setEditInstallmentNote]=useState('');

  useEffect(()=>{
    supabase.auth.getSession().then(({data})=>{setUser(data.session?.user??null);setAuthLoading(false);});
    const {data}=supabase.auth.onAuthStateChange((_event,session)=>{setUser(session?.user??null);setAuthLoading(false);});
    return ()=>data.subscription.unsubscribe();
  },[]);

  const loadWorkspace=useCallback(async(currentUser:User)=>{
    setLoadingData(true); setNotice('');
    try {
      const {data:membership,error:memberError}=await supabase.from('household_members').select('household_id').eq('user_id',currentUser.id).limit(1).maybeSingle();
      if(memberError) throw memberError;
      let homeId=membership?.household_id as string|undefined;
      const preferredName=String(currentUser.user_metadata?.display_name||currentUser.email?.split('@')[0]||'Usuário');
      if(!homeId){
        const {error:profileError}=await supabase.from('profiles').upsert({user_id:currentUser.id,display_name:preferredName}); if(profileError) throw profileError;
        const {data:home,error:homeError}=await supabase.from('households').insert({name:`Casa de ${preferredName}`,created_by:currentUser.id}).select('id').single(); if(homeError) throw homeError;
        homeId=home.id;
        const {error:joinError}=await supabase.from('household_members').insert({household_id:homeId,user_id:currentUser.id,role:'owner'}); if(joinError) throw joinError;
        const seeds=await Promise.all([
          supabase.from('household_settings').insert({household_id:homeId,monthly_limit:8000,alert_percentage:80,cutoff_day:0}),
          supabase.from('categories').insert([
            {household_id:homeId,name:'Alimentação',kind:'VARIAVEL',icon:'shopping_cart',color_hex:'#059669'},
            {household_id:homeId,name:'Transporte',kind:'VARIAVEL',icon:'directions_car',color_hex:'#1A365D'},
            {household_id:homeId,name:'Saúde',kind:'VARIAVEL',icon:'health',color_hex:'#DC6B5D'},
            {household_id:homeId,name:'Moradia',kind:'FIXO',icon:'home',color_hex:'#8250DF'},
            {household_id:homeId,name:'Assinatura',kind:'FIXO',icon:'subscriptions',color_hex:'#D97706'}]),
          supabase.from('financial_people').insert([
            {household_id:homeId,name:'Eu',calculation_percentage:100,include_in_calculation:true,is_default:true},
            {household_id:homeId,name:'Andressa',calculation_percentage:100,include_in_calculation:true,is_default:false},
            {household_id:homeId,name:'Os Dois',calculation_percentage:50,include_in_calculation:true,is_default:false}]),
          supabase.from('expense_sources').insert(['PIX','Cartão','Boleto','Dívida'].map(name=>({household_id:homeId,name})))
        ]);
        const failed=seeds.find(result=>result.error); if(failed?.error) throw failed.error;
      }
      const [profileResult,homeResult,categoryResult,peopleResult,originResult,settingsResult,expenseResult,personLinkResult]=await Promise.all([
        supabase.from('profiles').select('display_name').eq('user_id',currentUser.id).maybeSingle(),
        supabase.from('households').select('name').eq('id',homeId).single(),
        supabase.from('categories').select('id,name,kind,icon,color_hex').eq('household_id',homeId).order('name'),
        supabase.from('financial_people').select('id,name,calculation_percentage,include_in_calculation').eq('household_id',homeId).order('name'),
        supabase.from('expense_sources').select('id,name,due_day,closing_day,expiration_text,card_last_four').eq('household_id',homeId).order('name'),
        supabase.from('household_settings').select('monthly_limit').eq('household_id',homeId).single(),
        supabase.from('expenses').select('id,household_id,financial_person_id,amount,expense_date,occurrence_number,occurrence_count,note,category:categories(name),person:financial_people(name,calculation_percentage,include_in_calculation),origin:expense_sources(name),series:expense_series(kind)').order('expense_date',{ascending:false}),
        supabase.from('person_links').select('inviter_user_id,inviter_person_id,accepter_user_id,accepter_person_id')
      ]);
      const foundError=[profileResult,homeResult,categoryResult,peopleResult,originResult,settingsResult,expenseResult,personLinkResult].find(result=>result.error)?.error; if(foundError) throw foundError;
      const cats=(categoryResult.data??[]) as Category[]; const persons=(peopleResult.data??[]).map(item=>({...item,calculation_percentage:Number(item.calculation_percentage)})) as Person[]; const sources=(originResult.data??[]) as Source[];
      setHouseholdId(homeId!); setHouseholdName(homeResult.data!.name); setDisplayName(profileResult.data?.display_name||preferredName); setCategories(cats); setPeople(persons); setOrigins(sources); setBudget(Number(settingsResult.data!.monthly_limit));
      setCategory(current=>cats.some(item=>item.id===current)?current:cats[0]?.id||''); setPerson(current=>persons.some(item=>item.id===current)?current:persons.find(item=>item.name==='Os Dois')?.id||persons[0]?.id||''); setShareTargetPerson(current=>persons.some(item=>item.id===current)?current:persons.find(item=>item.name==='Os Dois')?.id||persons[0]?.id||''); setOrigin(current=>sources.some(item=>item.id===current)?current:sources.find(item=>item.name==='PIX')?.id||sources[0]?.id||'');
      type Row=Record<string,unknown>; const localPersonByRemoteId=new Map<string,Person>();
      for(const link of (personLinkResult.data??[]) as Row[]){const ownSide=String(link.inviter_user_id)===currentUser.id;const localId=String(ownSide?link.inviter_person_id:link.accepter_person_id);const remoteId=String(ownSide?link.accepter_person_id:link.inviter_person_id);const localPerson=persons.find(item=>item.id===localId);if(localPerson)localPersonByRemoteId.set(remoteId,localPerson);}
      setExpenses(((expenseResult.data??[]) as Row[]).map(row=>{
        const cat=row.category as {name?:string}|null; const remotePer=row.person as {name?:string;calculation_percentage?:number;include_in_calculation?:boolean}|null; const localPer=localPersonByRemoteId.get(String(row.financial_person_id)); const per=localPer??remotePer; const source=row.origin as {name?:string}|null; const series=row.series as {kind?:string}|null;
        return {id:String(row.id),title:String(row.note||cat?.name||'Lançamento'),note:String(row.note||''),category:cat?.name||'Sem categoria',person:per?.name||'Pessoa',origin:source?.name||'Origem',value:Number(row.amount),date:String(row.expense_date),installment:Number(row.occurrence_number),installments:Number(row.occurrence_count),series:series?.kind==='FIXED_RECURRENCE'?'fixed':series?.kind==='INSTALLMENT'?'installment':'single',percentage:Number(per?.calculation_percentage??100),included:per?.include_in_calculation??true,shared:String(row.household_id)!==homeId};
      }));
    } catch(error){setNotice(error instanceof Error?`Não foi possível carregar os dados: ${error.message}`:'Não foi possível carregar os dados.');}
    finally{setLoadingData(false);}
  },[]);
  useEffect(()=>{if(user) void loadWorkspace(user); else {setExpenses([]);setHouseholdId('');}},[user,loadWorkspace]);

  async function submitAuth(event:FormEvent){
    event.preventDefault(); setBusy(true); setAuthNotice('');
    try{
      if(authMode==='signup'){
        if(!authName.trim()) throw new Error('Informe seu nome.');
        const {data,error}=await supabase.auth.signUp({email:authEmail.trim(),password:authPassword,options:{data:{display_name:authName.trim()},emailRedirectTo:new URL('/gestao-de-custos/',window.location.origin).toString()}}); if(error) throw error;
        if(!data.session) setAuthNotice('Conta criada. Abra o e-mail de confirmação e depois volte para entrar.');
      } else {const {error}=await supabase.auth.signInWithPassword({email:authEmail.trim(),password:authPassword}); if(error) throw error;}
    }catch(error){setAuthNotice(error instanceof Error?error.message:'Não foi possível continuar.');}finally{setBusy(false);}
  }

  async function signInWithGoogle(){
    setBusy(true); setAuthNotice('');
    const {error}=await supabase.auth.signInWithOAuth({
      provider:'google',
      options:{redirectTo:new URL('/gestao-de-custos/',window.location.origin).toString()}
    });
    if(error){setAuthNotice(`Não foi possível entrar com Google: ${error.message}`);setBusy(false);}
  }

  async function saveExpense(event:FormEvent){
    event.preventDefault(); if(!user||!householdId)return;
    const parsed=Number(value.replace(/\./g,'').replace(',','.')); if(!parsed||parsed<=0){setNotice('Informe um valor válido.');return;} if(!category||!person||!origin){setNotice('Preencha categoria, pessoa e origem.');return;}
    setBusy(true);setNotice('');
    try{
      const quantity=Math.max(1,Math.min(120,installments)); const kind=fixed?'FIXED_RECURRENCE':quantity>1?'INSTALLMENT':'SINGLE';
      const {data:series,error:seriesError}=await supabase.from('expense_series').insert({household_id:householdId,kind,original_amount:parsed,occurrence_count:quantity,start_date:date,created_by:user.id}).select('id').single(); if(seriesError) throw seriesError;
      const base=Math.floor((parsed/quantity)*100)/100;
      const rows=Array.from({length:quantity},(_,index)=>({household_id:householdId,series_id:series.id,category_id:category,financial_person_id:person,source_id:origin,amount:fixed?parsed:index===quantity-1?Math.round((parsed-base*(quantity-1))*100)/100:base,expense_date:addMonths(date,index),occurrence_number:index+1,occurrence_count:quantity,note:note.trim()||null,created_by:user.id}));
      const {error}=await supabase.from('expenses').insert(rows); if(error) throw error;
      setValue('');setNote('');setInstallments(1);setFixed(false);setNotice(quantity===1?'Lançamento salvo na nuvem.':`${quantity} ocorrências salvas na nuvem.`);await loadWorkspace(user);
    }catch(error){setNotice(error instanceof Error?`Não foi possível salvar: ${error.message}`:'Não foi possível salvar.');}finally{setBusy(false);}
  }
  const catalogError=(error:{code?:string;message?:string}|null)=>error?.code==='23503'?'Este item já é usado em lançamentos e não pode ser excluído. Edite o nome se precisar.':error?.message||'Não foi possível concluir a operação.';
  async function saveCategory(event:FormEvent){
    event.preventDefault(); if(!user||!householdId||!categoryName.trim())return; setBusy(true);setNotice('');
    const values={name:categoryName.trim(),kind:categoryKind,icon:categoryIcon,color_hex:categoryKind==='FIXO'?'#8250DF':'#1A365D'};
    const result=editingCategory?await supabase.from('categories').update(values).eq('id',editingCategory).eq('household_id',householdId):await supabase.from('categories').insert({household_id:householdId,...values});
    if(result.error)setNotice(catalogError(result.error));else{setCategoryName('');setEditingCategory('');setCategoryKind('VARIAVEL');setCategoryIcon('category');setNotice(editingCategory?'Categoria atualizada.':'Categoria adicionada.');await loadWorkspace(user);}setBusy(false);
  }
  async function generateShareCode(personId:string){setBusy(true);setNotice('');const {data,error}=await supabase.rpc('generate_person_share_code',{p_person_id:personId});if(error)setNotice(`Não foi possível gerar o convite: ${error.message}`);else{const code=Array.isArray(data)?data[0]?.code:data?.code;setGeneratedShareCode(String(code||''));setNotice('Código criado. Ele vale por 24 horas e só pode ser usado uma vez.');}setBusy(false);}
  async function acceptShareCode(event:FormEvent){event.preventDefault();if(!shareCode.trim()||!shareTargetPerson)return;setBusy(true);setNotice('');const {error}=await supabase.rpc('accept_person_share_code',{p_code:shareCode.trim(),p_person_id:shareTargetPerson});if(error)setNotice(`Não foi possível vincular: ${error.message}`);else{setShareCode('');setGeneratedShareCode('');setNotice('Pessoas vinculadas. Os lançamentos compartilhados já podem aparecer para as duas contas.');if(user)await loadWorkspace(user);}setBusy(false);}
  async function savePerson(event:FormEvent){
    event.preventDefault(); if(!user||!householdId||!personName.trim())return; setBusy(true);setNotice('');
    const values={name:personName.trim(),calculation_percentage:Math.max(0,Math.min(100,personPercentage)),include_in_calculation:personIncluded};
    const result=editingPerson?await supabase.from('financial_people').update(values).eq('id',editingPerson).eq('household_id',householdId):await supabase.from('financial_people').insert({household_id:householdId,is_default:false,...values});
    if(result.error)setNotice(catalogError(result.error));else{setPersonName('');setEditingPerson('');setPersonPercentage(100);setPersonIncluded(true);setNotice(editingPerson?'Pessoa atualizada.':'Pessoa adicionada.');await loadWorkspace(user);}setBusy(false);
  }
  async function saveSource(event:FormEvent){
    event.preventDefault(); if(!user||!householdId||!sourceName.trim())return; setBusy(true);setNotice('');
    const day=(value:string)=>value?Math.max(1,Math.min(31,Number(value))):null; const lastFour=sourceLastFour.trim();
    if(lastFour&&!/^\d{4}$/.test(lastFour)){setNotice('Os últimos dígitos do cartão devem conter exatamente 4 números.');setBusy(false);return;}
    const values={name:sourceName.trim(),due_day:day(sourceDueDay),closing_day:day(sourceClosingDay),card_last_four:lastFour||null};
    const result=editingSource?await supabase.from('expense_sources').update(values).eq('id',editingSource).eq('household_id',householdId):await supabase.from('expense_sources').insert({household_id:householdId,...values});
    if(result.error)setNotice(catalogError(result.error));else{setSourceName('');setEditingSource('');setSourceDueDay('');setSourceClosingDay('');setSourceLastFour('');setNotice(editingSource?'Origem atualizada.':'Origem adicionada.');await loadWorkspace(user);}setBusy(false);
  }
  async function removeCatalog(table:'categories'|'financial_people'|'expense_sources',id:string,label:string){
    if(!user||!householdId||!window.confirm(`Excluir “${label}”?`))return; setBusy(true);setNotice('');
    const {error}=await supabase.from(table).delete().eq('id',id).eq('household_id',householdId);
    if(error)setNotice(catalogError(error));else{setNotice(`${label} excluído.`);await loadWorkspace(user);}setBusy(false);
  }
  async function removeExpense(){if(!user||!householdId||!editingInstallment||!window.confirm(`Excluir “${editingInstallment.title}”? Esta ação não pode ser desfeita.`))return;setBusy(true);setNotice('');const {error}=await supabase.from('expenses').delete().eq('id',editingInstallment.id).eq('household_id',householdId);if(error)setNotice(`Não foi possível excluir: ${error.message}`);else{setNotice('Lançamento excluído.');setEditingInstallment(null);await loadWorkspace(user);}setBusy(false);}
  function openInstallmentEditor(item:Expense){
    setEditingInstallment(item);setEditInstallmentValue(item.value.toFixed(2).replace('.',','));setEditInstallmentDate(item.date);setEditInstallmentCategory(categories.find(entry=>entry.name===item.category)?.id||'');setEditInstallmentPerson(people.find(entry=>entry.name===item.person)?.id||'');setEditInstallmentOrigin(origins.find(entry=>entry.name===item.origin)?.id||'');setEditInstallmentNote(item.note);
  }
  function editExpense(item:Expense){if(item.shared){setNotice('Este lançamento foi criado pela outra conta vinculada. Ele pode ser consultado aqui, mas deve ser editado pela conta que o cadastrou.');return;}setSelectedInstallmentMonth(item.date.slice(0,7));openInstallmentEditor(item);}
  async function saveInstallmentEdit(event:FormEvent){
    event.preventDefault();if(!user||!householdId||!editingInstallment)return;const parsed=Number(editInstallmentValue.replace(/\./g,'').replace(',','.'));if(!parsed||parsed<=0){setNotice('Informe um valor válido.');return;}if(!editInstallmentCategory||!editInstallmentPerson||!editInstallmentOrigin){setNotice('Preencha categoria, pessoa e origem.');return;}setBusy(true);setNotice('');
    const {error}=await supabase.from('expenses').update({amount:parsed,expense_date:editInstallmentDate,category_id:editInstallmentCategory,financial_person_id:editInstallmentPerson,source_id:editInstallmentOrigin,note:editInstallmentNote.trim()||null}).eq('id',editingInstallment.id).eq('household_id',householdId);
    if(error)setNotice(`Não foi possível atualizar: ${error.message}`);else{setNotice(editingInstallment.installments>1?'Parcela atualizada. As outras parcelas da sequência não foram alteradas.':'Lançamento atualizado.');setEditingInstallment(null);await loadWorkspace(user);}setBusy(false);
  }
  async function signOut(){setActiveTab('Início');setEditingInstallment(null);await supabase.auth.signOut();}
  function exportCsv(items:Expense[]=expenses){
    const header=['ID','Data','Descrição','Valor','Categoria','Pessoa','Percentual','Origem','Parcela','Total de parcelas','Tipo'];
    const lines=items.map(item=>[item.id,item.date,item.title,item.value.toFixed(2),item.category,item.person,item.percentage,item.origin,item.installment,item.installments,item.series]);
    const csv=[header,...lines].map(row=>row.map(cell=>`"${String(cell).replaceAll('"','""')}"`).join(';')).join('\r\n');
    const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));link.download=`gestao-de-custos-${today()}.csv`;link.click();URL.revokeObjectURL(link.href);
  }

  const currentMonth=today().slice(0,7); const monthExpenses=useMemo(()=>expenses.filter(item=>item.date.startsWith(currentMonth)),[expenses,currentMonth]); const committed=useMemo(()=>monthExpenses.reduce((sum,item)=>sum+(item.included?item.value*item.percentage/100:0),0),[monthExpenses]); const gross=useMemo(()=>monthExpenses.reduce((sum,item)=>sum+item.value,0),[monthExpenses]); const commitment=budget?Math.min(100,Math.round(committed/budget*100)):0; const monthLabel=new Date(`${currentMonth}-02T12:00:00`).toLocaleDateString('pt-BR',{month:'long'});
  const effectiveValue=(item:Expense)=>item.included?item.value*item.percentage/100:0;
  const summaryExpenses=useMemo(()=>expenses.filter(item=>item.date.startsWith(summaryMonth)),[expenses,summaryMonth]); const summaryCommitted=useMemo(()=>summaryExpenses.reduce((sum,item)=>sum+effectiveValue(item),0),[summaryExpenses]); const summaryGross=useMemo(()=>summaryExpenses.reduce((sum,item)=>sum+item.value,0),[summaryExpenses]); const summaryCommitment=budget?Math.min(100,Math.round(summaryCommitted/budget*100)):0; const summaryMonthLabel=new Date(`${summaryMonth}-02T12:00:00`).toLocaleDateString('pt-BR',{month:'long'});
  const categoryTotals=useMemo(()=>categories.map(entry=>({name:entry.name,color:entry.color_hex,total:summaryExpenses.filter(item=>item.category===entry.name).reduce((sum,item)=>sum+item.value,0)})).filter(item=>item.total>0).sort((a,b)=>b.total-a.total),[categories,summaryExpenses]);
  const personTotals=useMemo(()=>people.map((entry,index)=>({name:entry.name,color:chartColors[index%chartColors.length],total:summaryExpenses.filter(item=>item.person===entry.name).reduce((sum,item)=>sum+item.value,0)})).filter(item=>item.total>0).sort((a,b)=>b.total-a.total),[people,summaryExpenses]);
  const categoryChartTotal=categoryTotals.reduce((sum,item)=>sum+item.total,0); const personChartTotal=personTotals.reduce((sum,item)=>sum+item.total,0);
  const fixedTotal=useMemo(()=>summaryExpenses.filter(item=>categories.find(entry=>entry.name===item.category)?.kind==='FIXO').reduce((sum,item)=>sum+item.value,0),[categories,summaryExpenses]);
  const variableTotal=Math.max(0,summaryGross-fixedTotal);
  const installmentExpenses=expenses;
  const installmentMonths=useMemo(()=>Array.from(new Set(installmentExpenses.map(item=>item.date.slice(0,7)))).sort().map(key=>{const items=installmentExpenses.filter(item=>item.date.startsWith(key));return {key,items,total:items.reduce((sum,item)=>sum+item.value,0)};}),[installmentExpenses]);
  const selectedInstallments=useMemo(()=>installmentExpenses.filter(item=>item.date.startsWith(selectedInstallmentMonth)),[installmentExpenses,selectedInstallmentMonth]);
  const selectedInstallmentTotal=useMemo(()=>selectedInstallments.reduce((sum,item)=>sum+item.value,0),[selectedInstallments]);
  const futureInstallmentTotal=useMemo(()=>installmentExpenses.filter(item=>item.date.slice(0,7)>selectedInstallmentMonth).reduce((sum,item)=>sum+item.value,0),[installmentExpenses,selectedInstallmentMonth]);
  const maxInstallmentMonth=Math.max(1,...installmentMonths.map(item=>item.total));
  const selectedMonthLabel=new Date(`${selectedInstallmentMonth}-02T12:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
  useEffect(()=>{if(installmentMonths.length&&!installmentMonths.some(item=>item.key===selectedInstallmentMonth)){const closest=installmentMonths.find(item=>item.key>=currentMonth)??installmentMonths.at(-1);if(closest)setSelectedInstallmentMonth(closest.key);}},[installmentMonths,selectedInstallmentMonth,currentMonth]);
  useEffect(()=>{if(activeTab==='Lançamentos')requestAnimationFrame(()=>currentMonthCardRef.current?.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'}));},[activeTab,installmentMonths.length,currentMonth]);
  if(authLoading)return <main className="auth-shell"><div className="auth-card"><span className="brand-mark large">G</span><p>Preparando seu espaço…</p></div></main>;
  if(!user)return <main className="auth-shell"><section className="auth-card"><div className="auth-brand"><span className="brand-mark large">G</span><div><h1>Gestão de Custos</h1><p>Seus lançamentos seguros e acessíveis no Android e no iPhone.</p></div></div><button type="button" className="google-button" onClick={signInWithGoogle} disabled={busy}><span aria-hidden="true">G</span>Continuar com Google</button><div className="auth-divider"><span>ou use seu e-mail</span></div><div className="auth-tabs"><button className={authMode==='login'?'active':''} onClick={()=>setAuthMode('login')}>Entrar</button><button className={authMode==='signup'?'active':''} onClick={()=>setAuthMode('signup')}>Criar conta</button></div><form onSubmit={submitAuth} className="auth-form">{authMode==='signup'&&<label><span>Seu nome</span><input value={authName} onChange={e=>setAuthName(e.target.value)} autoComplete="name" required /></label>}<label><span>E-mail</span><input type="email" value={authEmail} onChange={e=>setAuthEmail(e.target.value)} autoComplete="email" required /></label><label><span>Senha</span><input type="password" minLength={6} value={authPassword} onChange={e=>setAuthPassword(e.target.value)} autoComplete={authMode==='login'?'current-password':'new-password'} required /></label><button className="save auth-submit" disabled={busy}>{busy?'Aguarde…':authMode==='login'?'Entrar':'Criar minha conta'}</button>{authNotice&&<p className="auth-notice" role="status">{authNotice}</p>}</form><small className="privacy-note">Cada casa possui uma área privada. Apenas usuários autorizados conseguem acessar os dados.</small></section></main>;
  const navigation=<>{navItems.map(([icon,label])=><button type="button" className={`nav-item ${activeTab===label?'active':''}`} key={label} onClick={()=>setActiveTab(label)}><span>{icon}</span><span>{label}</span></button>)}</>;
  return <main className="app-shell"><aside className="sidebar"><div className="brand"><span className="brand-mark">G</span><span>Gestão de Custos</span></div><nav aria-label="Navegação principal">{navigation}</nav><div className="sidebar-foot"><span className="avatar">{displayName.charAt(0).toUpperCase()}</span><div><strong>{displayName}</strong><small>{householdName}</small></div><button type="button" className="logout" onClick={signOut} title="Sair">↪</button></div></aside><section className="workspace"><header className="topbar"><div><p className="eyebrow">DADOS PROTEGIDOS NA NUVEM</p><h1>{activeTab==='Início'?`Olá, ${displayName.split(' ')[0]}`:activeTab}</h1></div><div className="topbar-actions"><div className="status"><span /> {loadingData?'Sincronizando…':'Sincronizado'}</div><button type="button" className="topbar-logout" onClick={signOut} title="Sair da conta"><span>↪</span> Sair</button></div></header>
  {activeTab==='Início'&&<div className="content-grid"><div className="primary-column"><section className="hero-card"><div><p className="eyebrow light">ORÇAMENTO DE {monthLabel.toUpperCase()}</p><h2>{money(committed)}</h2><p>comprometidos de {money(budget)}</p></div><div><div className="progress-label"><span>{commitment}% utilizado</span><strong>{money(Math.max(0,budget-committed))} disponíveis</strong></div><div className="progress"><span style={{width:`${commitment}%`}} /></div></div></section><section className="panel entry-panel"><div className="panel-title"><div><p className="eyebrow">NOVO LANÇAMENTO</p><h2>Registrar gasto</h2></div><span className="entry-badge">Rápido e seguro</span></div><form onSubmit={saveExpense}><div className="form-grid"><label className="value-field"><span>Valor do gasto</span><div><b>R$</b><input value={value} onChange={e=>setValue(e.target.value)} inputMode="decimal" placeholder="0,00" /></div></label><label><span>Data</span><input type="date" value={date} onChange={e=>setDate(e.target.value)} /></label><label><span>Categoria</span><select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label><span>Pessoa</span><select value={person} onChange={e=>setPerson(e.target.value)}>{people.map(item=><option value={item.id} key={item.id}>{item.name} ({item.calculation_percentage}%)</option>)}</select></label><label><span>Origem</span><select value={origin} onChange={e=>setOrigin(e.target.value)}>{origins.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label><span>Observação</span><input value={note} onChange={e=>setNote(e.target.value)} placeholder="Opcional" /></label><label><span>{fixed?'Quantidade de meses':'Quantidade de parcelas'}</span><input type="number" min="1" max="120" value={installments} onChange={e=>setInstallments(Number(e.target.value))} /></label></div><div className="form-footer"><label className="check"><input type="checkbox" checked={fixed} onChange={e=>setFixed(e.target.checked)} /> Custo fixo mensal</label><div className="actions"><button type="button" className="attach">＋ Anexar</button><button type="submit" className="save" disabled={busy}>{busy?'Salvando…':'Salvar lançamento'}</button></div></div>{notice&&<p className="form-notice" role="status">{notice}</p>}</form></section></div><aside className="secondary-column"><section className="panel recent-panel"><div className="panel-title"><div><p className="eyebrow">MOVIMENTAÇÕES</p><h2>Recentes</h2></div><button type="button" className="link-button" onClick={()=>setActiveTab('Resumo')}>Ver todas</button></div><div className="expense-list">{monthExpenses.slice(0,5).map(item=><button type="button" className="expense" key={item.id} onClick={()=>editExpense(item)}><span className="expense-icon">{categorySymbol(categories.find(entry=>entry.name===item.category)?.icon||'category')}</span><div><strong>{item.title}{item.shared&&<em className="shared-badge">Compartilhado</em>}</strong><small>{item.category} · {item.person} · {item.origin}{item.installments>1?` · ${item.installment}/${item.installments}`:''}</small></div><b>{money(item.value)}</b><span className="row-chevron">›</span></button>)}{!monthExpenses.length&&<p className="empty-copy">Nenhum lançamento neste mês.</p>}</div></section><section className="insight-card"><span className="insight-icon">↗</span><div><p className="eyebrow">REGRA PRESERVADA</p><h3>“Os Dois” calcula 50%</h3><p>O valor integral fica salvo; o comprometimento usa o percentual configurado.</p></div></section></aside></div>}
  {activeTab==='Resumo'&&<section className="summary-page"><section className="summary-filter"><button type="button" onClick={()=>setSummaryMonth(addMonths(summaryMonth+'-01',-1).slice(0,7))} aria-label="Mês anterior">‹</button><label><span>Período do resumo</span><input type="month" value={summaryMonth} onChange={e=>setSummaryMonth(e.target.value)} /></label><button type="button" onClick={()=>setSummaryMonth(addMonths(summaryMonth+'-01',1).slice(0,7))} aria-label="Próximo mês">›</button>{summaryMonth!==currentMonth&&<button type="button" className="current-month-button" onClick={()=>setSummaryMonth(currentMonth)}>Mês atual</button>}</section><section className="panel period-card"><div><p className="eyebrow">RESUMO FINANCEIRO</p><h2>{summaryMonthLabel.charAt(0).toUpperCase()+summaryMonthLabel.slice(1)} de {summaryMonth.slice(0,4)}</h2><small>{summaryMonth===currentMonth?'Mês atual':'Período selecionado'} · {summaryExpenses.length} lançamentos</small></div><strong>{money(summaryCommitted)}<small>Total comprometido</small></strong></section><article className={`panel commitment-wide ${summaryCommitment>=80?'alert':''}`}><div><span>Comprometimento ({summaryMonthLabel})</span><b>{summaryCommitment}%</b></div><div><span>Limite global</span><strong>{money(budget)}</strong></div><i><em style={{width:`${summaryCommitment}%`}} /></i><p>Consumido: {money(summaryCommitted)}</p></article><div className="summary-visuals old-app-charts"><article className="panel chart-card donut-card"><div className="chart-heading"><div><p className="eyebrow">DISTRIBUIÇÃO</p><h2>Gastos por categoria</h2></div></div><div className="donut-layout"><div className="donut multi" style={{background:donutBackground(categoryTotals,categoryChartTotal)}}><span><small>Total</small><b>{money(summaryCommitted)}</b></span></div><div className="donut-legend">{categoryTotals.map((item,index)=><div key={item.name}><i style={{background:item.color||chartColors[index%chartColors.length]}} /><span>{item.name}</span><b>{Math.round(item.total/summaryCommitted*100)}%</b><small>{money(item.total)}</small></div>)}</div></div></article><article className="panel chart-card donut-card"><div className="chart-heading"><div><p className="eyebrow">RESPONSÁVEIS</p><h2>Gastos por pessoa</h2></div></div><div className="donut-layout"><div className="donut multi" style={{background:donutBackground(personTotals,personChartTotal)}}><span><small>Pessoas</small><b>{personTotals.length}</b></span></div><div className="donut-legend">{personTotals.map(item=><div key={item.name}><i style={{background:item.color}} /><span>{item.name}</span><b>{Math.round(item.total/summaryCommitted*100)}%</b><small>{money(item.total)}</small></div>)}</div></div></article><article className="panel chart-card fixed-variable-card"><div className="chart-heading"><div><p className="eyebrow">COMPOSIÇÃO</p><h2>Custos fixos vs variáveis</h2></div></div><div className="cost-row"><div><span>Custos fixos</span><b>{money(fixedTotal)} ({summaryCommitted?Math.round(fixedTotal/summaryCommitted*100):0}%)</b></div><i><em className="fixed-bar" style={{width:`${summaryCommitted?fixedTotal/summaryCommitted*100:0}%`}} /></i></div><div className="cost-row"><div><span>Custos variáveis</span><b>{money(variableTotal)} ({summaryCommitted?Math.round(variableTotal/summaryCommitted*100):0}%)</b></div><i><em className="variable-bar" style={{width:`${summaryCommitted?variableTotal/summaryCommitted*100:0}%`}} /></i></div></article></div><section className="panel full-panel summary-expenses"><div className="table-head"><div><p className="eyebrow">MÊS ATUAL</p><h2>Lançamentos do período ({summaryExpenses.length})</h2></div><button type="button" className="attach" onClick={()=>exportCsv(summaryExpenses)}>⇩ Exportar CSV</button></div><div className="data-list">{summaryExpenses.map(item=><button type="button" className="data-row" key={item.id} onClick={()=>editExpense(item)}><span>{new Date(item.date+'T12:00:00').toLocaleDateString('pt-BR')}</span><strong>{item.title}{item.installments>1&&<em>{item.installment}/{item.installments}</em>}</strong><small>{item.person} · {item.category} · {item.origin}</small><b>{money(item.value)}</b><span className="row-chevron">›</span></button>)}{!summaryExpenses.length&&<p className="empty-copy">Nenhum lançamento no mês atual.</p>}</div></section></section>}
  {activeTab==='Lançamentos'&&<section className="installments-page"><section className="panel installment-timeline"><div className="panel-title"><div><p className="eyebrow">PASSADO E FUTURO</p><h2>Total de gastos por mês</h2></div><span className="timeline-help">Toque em um mês para abrir</span></div>{installmentMonths.length?<div className="month-strip">{installmentMonths.map((item,index)=>{const position=Math.max(12,Math.round(item.total/maxInstallmentMonth*58));const previousTotal=installmentMonths[index-1]?.total??item.total;const nextTotal=installmentMonths[index+1]?.total??item.total;const previousPosition=Math.max(12,Math.round(previousTotal/maxInstallmentMonth*58));const nextPosition=Math.max(12,Math.round(nextTotal/maxInstallmentMonth*58));const selected=item.key===selectedInstallmentMonth;const period=item.key<currentMonth?'past':item.key===currentMonth?'current':'future';return <button ref={item.key===currentMonth?currentMonthCardRef:null} type="button" key={item.key} className={`month-card ${selected?'selected':''} ${period}`} onClick={()=>{setSelectedInstallmentMonth(item.key);setEditingInstallment(null)}}><strong>{new Date(`${item.key}-02T12:00:00`).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</strong><span className="month-year">{item.key.slice(0,4)}</span><span className="month-chart"><svg className="month-line" viewBox="0 0 138 78" preserveAspectRatio="none" aria-hidden="true"><line className="left-line" x1="-7" y1={70-previousPosition} x2="69" y2={70-position} /><line className="right-line" x1="69" y1={70-position} x2="145" y2={70-nextPosition} /><circle cx="69" cy={70-position} r="6" /></svg></span><em>{money(item.total)}</em></button>})}</div>:<p className="empty-copy">Nenhum lançamento encontrado.</p>}</section><section className="installment-summary"><article><small>Total em {selectedMonthLabel}</small><strong>{money(selectedInstallmentTotal)}</strong></article><article><small>Lançamentos no mês</small><strong>{selectedInstallments.length}</strong></article><article><small>Depois deste mês</small><strong>{money(futureInstallmentTotal)}</strong></article></section><section className="panel installment-details"><div className="panel-title"><div><p className="eyebrow">DETALHAMENTO</p><h2>Lançamentos de {selectedMonthLabel}</h2></div></div><div className="installment-list">{selectedInstallments.map(item=><button type="button" className={`installment-row ${editingInstallment?.id===item.id?'selected':''}`} key={item.id} onClick={()=>openInstallmentEditor(item)}><span className={`installment-number ${item.installments===1?'single':''}`}>{item.installments>1?<>{item.installment}<small>de {item.installments}</small></>:<>{new Date(item.date+'T12:00:00').getDate()}<small>dia</small></>}</span><span className="installment-copy"><strong>{item.title}</strong><small>{item.category} · {item.person} · {item.origin}</small></span><time>{new Date(item.date+'T12:00:00').toLocaleDateString('pt-BR')}</time><b>{money(item.value)}</b><span className="edit-hint">Editar ›</span></button>)}{!selectedInstallments.length&&<p className="empty-copy">Não há lançamentos neste mês.</p>}</div></section></section>}
  {activeTab==='Cadastros'&&<div className="catalog-tabs" role="tablist" aria-label="Tipos de cadastro">{(['Categorias','Pessoas','Origens'] as const).map(item=><button type="button" role="tab" aria-selected={catalogSection===item} className={catalogSection===item?'active':''} key={item} onClick={()=>{setCatalogSection(item);setNotice('');if(item!=='Pessoas')setGeneratedShareCode('')}}>{item}</button>)}</div>}
  {activeTab==='Cadastros'&&catalogSection==='Categorias'&&<section className="catalog-layout"><form className={`panel catalog-form ${editingCategory?'editing':''}`} onSubmit={saveCategory}><div className="panel-title"><div><p className="eyebrow">{editingCategory?'EDITAR':'NOVA'} CATEGORIA</p><h2>{editingCategory?'Atualizar categoria':'Adicionar categoria'}</h2></div></div><label><span>Nome</span><input value={categoryName} onChange={e=>setCategoryName(e.target.value)} placeholder="Ex.: Educação" required /></label><label><span>Tipo</span><select value={categoryKind} onChange={e=>setCategoryKind(e.target.value as 'FIXO'|'VARIAVEL')}><option value="VARIAVEL">Variável</option><option value="FIXO">Fixo</option></select></label><label><span>Ícone</span><div className="icon-picker">{categoryIcons.map(([key,symbol])=><button type="button" className={categoryIcon===key?'active':''} key={key} onClick={()=>setCategoryIcon(key)} title={key}>{symbol}</button>)}</div></label><div className="catalog-form-actions">{editingCategory&&<button type="button" className="attach" onClick={()=>{setEditingCategory('');setCategoryName('');setCategoryKind('VARIAVEL');setCategoryIcon('category')}}>Cancelar</button>}<button className="save" disabled={busy}>{editingCategory?'Salvar alterações':'Adicionar'}</button></div>{notice&&<p className="form-notice" role="status">{notice}</p>}</form><section className="panel catalog-panel"><div className="panel-title"><div><p className="eyebrow">ORGANIZAÇÃO</p><h2>Suas categorias</h2></div><span className="count-badge">{categories.length}</span></div><div className="catalog-list">{categories.map(item=><article key={item.id}><span className="catalog-icon">{categorySymbol(item.icon)}</span><div><strong>{item.name}</strong><small>{item.kind==='FIXO'?'Custo fixo':'Custo variável'}</small></div><div className="row-actions"><button type="button" onClick={()=>{setEditingCategory(item.id);setCategoryName(item.name);setCategoryKind(item.kind);setCategoryIcon(item.icon||'category')}}>Editar</button><button type="button" className="danger" onClick={()=>removeCatalog('categories',item.id,item.name)}>Excluir</button></div></article>)}</div></section></section>}
  {activeTab==='Cadastros'&&catalogSection==='Pessoas'&&<section className="catalog-layout"><form className={`panel catalog-form ${editingPerson?'editing':''}`} onSubmit={savePerson}><div className="panel-title"><div><p className="eyebrow">{editingPerson?'EDITAR':'NOVA'} PESSOA</p><h2>{editingPerson?'Atualizar pessoa':'Adicionar pessoa'}</h2></div></div><label><span>Nome</span><input value={personName} onChange={e=>setPersonName(e.target.value)} placeholder="Nome da pessoa" required /></label><label><span>Percentual considerado</span><input type="number" min="0" max="100" value={personPercentage} onChange={e=>setPersonPercentage(Number(e.target.value))} /></label><label className="check catalog-check"><input type="checkbox" checked={personIncluded} onChange={e=>setPersonIncluded(e.target.checked)} /> Incluir nos cálculos do orçamento</label><div className="catalog-form-actions">{editingPerson&&<button type="button" className="attach" onClick={()=>{setEditingPerson('');setPersonName('');setPersonPercentage(100);setPersonIncluded(true)}}>Cancelar</button>}<button className="save" disabled={busy}>{editingPerson?'Salvar alterações':'Adicionar'}</button></div>{notice&&<p className="form-notice" role="status">{notice}</p>}</form><section className="panel catalog-panel"><div className="panel-title"><div><p className="eyebrow">DIVISÃO DOS GASTOS</p><h2>Pessoas</h2></div><span className="count-badge">{people.length}</span></div><section className="share-panel"><div><p className="eyebrow">COMPARTILHAMENTO SEGURO</p><h3>Vincular uma pessoa</h3><small>Recebeu um código? Escolha qual pessoa desta conta será conectada.</small></div><form onSubmit={acceptShareCode}><input value={shareCode} onChange={e=>setShareCode(e.target.value.toUpperCase())} maxLength={8} placeholder="Código de 8 caracteres" /><select value={shareTargetPerson} onChange={e=>setShareTargetPerson(e.target.value)}>{people.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><button className="save" disabled={busy||!shareCode.trim()}>Vincular</button></form>{generatedShareCode&&<div className="generated-code"><small>Envie este código para a outra pessoa:</small><strong>{generatedShareCode}</strong><button type="button" onClick={()=>navigator.clipboard.writeText(generatedShareCode)}>Copiar código</button></div>}</section><div className="catalog-list">{people.map(item=><article key={item.id}><span className="catalog-icon person-icon">{item.name.charAt(0).toUpperCase()}</span><div><strong>{item.name}</strong><small>{item.include_in_calculation?`${item.calculation_percentage}% considerado`:'Fora do cálculo'}</small></div><div className="row-actions"><button type="button" className="share-action" onClick={()=>generateShareCode(item.id)}>Compartilhar</button><button type="button" onClick={()=>{setEditingPerson(item.id);setPersonName(item.name);setPersonPercentage(item.calculation_percentage);setPersonIncluded(item.include_in_calculation)}}>Editar</button><button type="button" className="danger" onClick={()=>removeCatalog('financial_people',item.id,item.name)}>Excluir</button></div></article>)}</div></section></section>}
  {activeTab==='Cadastros'&&catalogSection==='Origens'&&<section className="catalog-layout"><form className={`panel catalog-form ${editingSource?'editing':''}`} onSubmit={saveSource}><div className="panel-title"><div><p className="eyebrow">{editingSource?'EDITAR':'NOVA'} ORIGEM</p><h2>{editingSource?'Atualizar origem':'Adicionar origem'}</h2></div></div><label><span>Nome</span><input value={sourceName} onChange={e=>setSourceName(e.target.value)} placeholder="Ex.: Cartão principal" required /></label><div className="compact-fields"><label><span>Dia do vencimento</span><input type="number" min="1" max="31" value={sourceDueDay} onChange={e=>setSourceDueDay(e.target.value)} placeholder="Opcional" /></label><label><span>Dia do fechamento</span><input type="number" min="1" max="31" value={sourceClosingDay} onChange={e=>setSourceClosingDay(e.target.value)} placeholder="Opcional" /></label></div><label><span>Últimos 4 dígitos</span><input inputMode="numeric" maxLength={4} value={sourceLastFour} onChange={e=>setSourceLastFour(e.target.value.replace(/\D/g,''))} placeholder="Somente para cartão" /></label><div className="catalog-form-actions">{editingSource&&<button type="button" className="attach" onClick={()=>{setEditingSource('');setSourceName('');setSourceDueDay('');setSourceClosingDay('');setSourceLastFour('')}}>Cancelar</button>}<button className="save" disabled={busy}>{editingSource?'Salvar alterações':'Adicionar'}</button></div>{notice&&<p className="form-notice" role="status">{notice}</p>}</form><section className="panel catalog-panel"><div className="panel-title"><div><p className="eyebrow">FORMAS DE PAGAMENTO</p><h2>Origens</h2></div><span className="count-badge">{origins.length}</span></div><div className="catalog-list">{origins.map(item=><article key={item.id}><span className="catalog-icon">◇</span><div><strong>{item.name}{item.card_last_four?` •••• ${item.card_last_four}`:''}</strong><small>{item.due_day?`Vence dia ${item.due_day}`:'Sem vencimento'}{item.closing_day?` · Fecha dia ${item.closing_day}`:''}</small></div><div className="row-actions"><button type="button" onClick={()=>{setEditingSource(item.id);setSourceName(item.name);setSourceDueDay(item.due_day?String(item.due_day):'');setSourceClosingDay(item.closing_day?String(item.closing_day):'');setSourceLastFour(item.card_last_four||'')}}>Editar</button><button type="button" className="danger" onClick={()=>removeCatalog('expense_sources',item.id,item.name)}>Excluir</button></div></article>)}</div></section></section>}
  {editingInstallment&&<form className="installment-editor" onSubmit={saveInstallmentEdit}><div className="editor-heading"><div><p className="eyebrow">EDITAR REGISTRO</p><h3>{editingInstallment.installments>1?`${editingInstallment.installment} de ${editingInstallment.installments} · `:''}{editingInstallment.title}</h3></div><button type="button" className="editor-close" onClick={()=>setEditingInstallment(null)} aria-label="Fechar edição">×</button></div><div className="form-grid"><label className="value-field"><span>Valor do lançamento</span><div><b>R$</b><input value={editInstallmentValue} onChange={e=>setEditInstallmentValue(e.target.value)} inputMode="decimal" required /></div></label><label><span>Data</span><input type="date" value={editInstallmentDate} onChange={e=>setEditInstallmentDate(e.target.value)} required /></label><label><span>Categoria</span><select value={editInstallmentCategory} onChange={e=>setEditInstallmentCategory(e.target.value)}>{categories.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label><span>Pessoa</span><select value={editInstallmentPerson} onChange={e=>setEditInstallmentPerson(e.target.value)}>{people.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label><span>Origem</span><select value={editInstallmentOrigin} onChange={e=>setEditInstallmentOrigin(e.target.value)}>{origins.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label><span>Observação</span><input value={editInstallmentNote} onChange={e=>setEditInstallmentNote(e.target.value)} placeholder="Opcional" /></label></div><div className="catalog-form-actions editor-actions"><button type="button" className="danger-button" onClick={removeExpense} disabled={busy}>Excluir</button><button type="button" className="attach" onClick={()=>setEditingInstallment(null)}>Cancelar</button><button className="save" disabled={busy}>{busy?'Salvando…':'Salvar registro'}</button></div>{notice&&<p className="form-notice" role="status">{notice}</p>}</form>}
  <nav className="mobile-nav" aria-label="Navegação móvel">{navItems.map(([icon,label])=><button type="button" className={activeTab===label?'active':''} key={label} onClick={()=>setActiveTab(label)}><span>{icon}</span><small>{label}</small></button>)}</nav></section></main>;
}

